// Generated by generators/calendar/src/GenCalendar.lex.tex from the IANA iCalendar Element Registries and RFC 5545's own
// examples (test/standards/generated/rfc5545-examples.txt), both pinned in app/specs/calendar/spec.json. Do not edit.
// Each test enforces one registered element (ST-01): the examples RFC 5545 section 3 gives for it derive from the element's
// own rule of RFC 5545's grammar, through the page's LexLean reader (the grammar-ical guest, site/read/abnf.mjs). An example
// the grammar refuses must be one the spec lists under 'slips', and every slip listed must be refused.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import ical from '../site/read/grammar/ical.mjs';
import { abnf, all, first } from '../site/read/abnf.mjs';

const CRLF = String.fromCharCode(13, 10);
const grammar = abnf(ical);
const slips = JSON.parse(readFileSync('app/specs/calendar/spec.json', 'utf8')).slips.map((slip) => slip.line);
// The examples as content lines: X opens one, F and G continue it (a fold; G keeps a space), C is a remark beside it,
// as is what follows two spaces and a semicolon, or the ==> that opens the instances a rule gives; a remark ends the line.
// P and Q stand for a row left out because it holds a number shaped like a telephone number (no such number is kept in
// the repository): P opened a line and Q continued one, and that example is not read.
const rows = [];
for (const row of readFileSync('test/standards/generated/rfc5545-examples.txt', 'utf8').split(String.fromCharCode(10)).filter(Boolean)) {
  const [mark, sec, ...words] = row.split(' ');
  if (mark === 'X' || mark === 'P') rows.push({ sec, line: words.join(' ').split('  ;')[0].trimEnd(), held: mark === 'P' });
  else if (mark === 'Q') rows.at(-1).held = true;
  else if (mark === 'C' || words[0] === '==>') rows.at(-1).shut = true;
  else if (!rows.at(-1).shut) rows.at(-1).line += (mark === 'G' ? ' ' : '') + words.join(' ');
}
const lines = rows.filter((row) => !row.held);
const lit = (part) => (part && part[0] === 'lit' ? part[1].toUpperCase() : '');
const rules = Object.entries(ical.rules).filter(([, rule]) => rule[0] === 'seq');
const ruleOf = {
  property: (name) => rules.find(([, rule]) => lit(rule[1]) === name && lit(rule[2]) !== '=')?.[0],
  parameter: (name) => rules.find(([, rule]) => lit(rule[1]) === name && lit(rule[2]) === '=')?.[0],
  component: (name) => rules.find(([, rule]) => lit(rule[1]) === 'BEGIN' && lit(rule[3]) === name)?.[0],
  // A value type's rule has its name, unless a property has it too: then it is the rule that property's value refers to.
  value: (name) => (ruleOf.property(name) ? ical.rules[ruleOf.property(name)].filter((part) => part[0] === 'ref').at(-2)[1] : name.toLowerCase()),
};
const derives = (rule, text) => Boolean(rule && grammar.match(rule, text));
const read = new Map();
const lineOf = (line) => read.get(line) ?? read.set(line, grammar.match('contentline', line + CRLF)).get(line);
let found;
const params = () => (found ??= lines.flatMap(({ line }) => all(lineOf(line), 'param').map((param) => ({ name: first(param, 'param-name').text.toUpperCase(), text: param.text, line }))));
const named = (name) => lines.filter(({ line }) => [name + ':', name + ';'].includes(line.slice(0, name.length + 1).toUpperCase()));
const refused = new Set();
// Every example of the element derives from its rule, or is a slip; at least one derives.
function each(examples, rule, text) {
  const good = examples.filter((example) => derives(rule, text(example)) || !refused.add(example.line));
  assert.ok(rule && good.length, 'no example derives from ' + rule);
}
function reads(kind, name, sec) {
  const [field, value] = name.split('=');
  if (kind === 'property') each(named(name), ruleOf.property(name), ({ line }) => line + CRLF);
  else if (kind === 'parameter') each(params().filter((param) => param.name === name), ruleOf.parameter(name), (param) => param.text);
  else if (kind === 'enum' && ruleOf.parameter(field)) each(params().filter((param) => param.text.toUpperCase().split(',').join('=').split('=').slice(1).includes(value) && param.name === field), ruleOf.parameter(field), (param) => param.text);
  else if (kind === 'enum') each(named(field).filter(({ line }) => line.toUpperCase() === field + ':' + value), ruleOf.property(field), ({ line }) => line + CRLF);
  else if (kind === 'value') assert.ok(lines.some(({ sec: its, line }) => its === sec && (derives(ruleOf.value(name), line) || derives(ruleOf.value(name), first(lineOf(line), 'value')?.text ?? CRLF))), 'no example of section ' + sec + ' derives from ' + ruleOf.value(name));
  else {
    // A component's examples: each run of lines from its BEGIN to its END, whole.
    const blocks = [];
    for (const { line } of lines) {
      if (line.toUpperCase() === 'BEGIN:' + name) blocks.push({ line: '', open: true });
      if (blocks.at(-1)?.open) blocks.at(-1).line += line + CRLF;
      if (line.toUpperCase() === 'END:' + name && blocks.length) blocks.at(-1).open = false;
    }
    each(blocks.filter((block) => !block.open), ruleOf.component(name), (block) => block.line);
  }
}

// enforces: rfc5545-component-VCALENDAR
test('component VCALENDAR', () => reads('component', 'VCALENDAR', '3.4'));
